function normalizeBatch(p){
  const bad=()=>{throw Error("MESH_INVALID_REVIEW_PACKET");};
  const obj=v=>v!==null&&typeof v==="object"&&!Array.isArray(v);
  const keys=(v,allowed)=>obj(v)&&Object.keys(v).every(k=>allowed.includes(k));
  const stamp=v=>typeof v==="string"&&/^\d{4}-\d\d-\d\dT/.test(v)&&/(Z|[+-]\d\d:\d\d)$/.test(v)&&Number.isFinite(Date.parse(v));
  const number=v=>typeof v==="string"&&/^[1-9]\d{0,15}$/.test(v);
  const sha=v=>typeof v==="string"&&/^[0-9a-f]{64}$/.test(v);
  const commit=v=>typeof v==="string"&&/^[0-9a-f]{40}$/.test(v);
  const repo="2strongtrainers-art/Nicholas-AI-OS";
  const base="https://github.com/"+repo;
  if(!keys(p,["schema","batch_id","as_of","records"])||p.schema!=="trivalley-chief-review-batch-v1"||
     typeof p.batch_id!=="string"||!/^[-A-Za-z0-9_]{1,52}$/.test(p.batch_id)||
     !stamp(p.as_of)||!Array.isArray(p.records)||p.records.length<1||p.records.length>6)bad();
  const asOf=Date.parse(p.as_of);const rows=[];const seen=new Set();const statuses=[];
  for(const packet of p.records){
    if(!keys(packet,["kind","handoff","index_receipt","market_receipt"]))bad();
    const kind=packet.kind;
    if(!["argus","repo_category","market_desk"].includes(kind)||seen.has(kind))bad();
    seen.add(kind);
    let status,reason,id,version,url,nextStep,priority,observedAt,receiptKey,proof;
    if(kind==="argus"){
      if(!keys(packet,["kind","handoff"])||!obj(packet.handoff))bad();
      const h=packet.handoff,r=h.run,ver=h.verification,art=h.reviewed_artifact;
      if(!keys(h,['schema','status','reason','receipt_key','run','verification','reviewed_artifact','n8n_execution_id','chief_delivery','chief_snapshot','limitations'])||
        !keys(r,['run_id','run_attempt','head_sha','run_url','status','conclusion'])||
        (ver!==null&&!keys(ver,['status','failure_code','observed_at','evidence']))||
        (art!==null&&!keys(art,['artifact_id','name','archive_sha256','provenance'])))bad();
      if(h.schema!=="argus-chief-handoff-v1"||!obj(r)||!number(r.run_id)||
        !Number.isSafeInteger(r.run_attempt)||r.run_attempt<1||!commit(r.head_sha)||
        r.run_url!==base+"/actions/runs/"+r.run_id+"/attempts/"+r.run_attempt||
        !number(h.n8n_execution_id)||h.receipt_key!=="argus-"+r.run_id+"-"+r.run_attempt||
        !["VERIFIED_SYNTHETIC","BLOCKED","FAILED","UNVERIFIED"].includes(h.status)||
        h.chief_delivery!=="normalized_output_prepared; acknowledgment_not_observed")bad();
      status=h.status;reason=h.reason;url=r.run_url;receiptKey=h.receipt_key;
      if(status==="VERIFIED_SYNTHETIC"){
        const e=ver?.evidence,ex=e?.exiftool;
        if(!keys(e,['fixture_id','source_bytes','source_sha256','unauthenticated_http','authenticated_http','exiftool','sensitive_metadata_included'])||
          !keys(ex,['FileType','MIMEType','ImageWidth','ImageHeight'])||
          reason!=="reviewed_synthetic_receipt_matches_github"||r.conclusion!=="success"||
          ver?.status!=="ARGUS_SYNTHETIC_PASS"||ver.failure_code!==null||
          !stamp(ver.observed_at)||!obj(e)||e.fixture_id!=="argus-synthetic-png-v1"||
          e.source_bytes!==69||e.source_sha256!=="5731a25f0c25c4e8b515f273b778da29ec74369400f93551a68507d5dacf77c3"||
          e.unauthenticated_http!==401||e.authenticated_http!==200||e.sensitive_metadata_included!==false||
          !obj(ex)||ex.FileType!=="PNG"||ex.MIMEType!=="image/png"||ex.ImageWidth!==1||ex.ImageHeight!==1||
          !obj(art)||!Number.isSafeInteger(art.artifact_id)||art.artifact_id<1||!sha(art.archive_sha256))bad();
        observedAt=ver.observed_at;
      }else{
        const reasons=["worker_not_configured","github_key_missing","run_not_successful",
          "sanitized_receipt_not_reviewed","matching_artifact_unavailable","github_run_source_unavailable",
          "run_not_completed","prerequisite_failed","authenticated_analysis_failed","synthetic_integrity_failed",
          "unauthorized_check_failed","reviewed_artifact_provenance_mismatch","sanitized_receipt_invalid",
          "run_receipt_conflict","health_unverified","worker_request_failed","exiftool_unverified"];
        if(typeof reason!=="string"||!reasons.includes(reason))bad();
        observedAt=stamp(ver?.observed_at)?ver.observed_at:p.as_of;
      }
      id="argus-verification";version=receiptKey+":"+status+":"+reason;
      nextStep=status==="VERIFIED_SYNTHETIC"?"Chief must acknowledge this reviewed synthetic pass; real-image and unattended delivery acceptance remain separate.":"Resolve the exact ARGUS verification blocker; review the new artifact and repeat the manual evidence handoff.";
      priority=status==="VERIFIED_SYNTHETIC"?"normal":"high";proof=status==="VERIFIED_SYNTHETIC"?"reviewed_synthetic_receipt":"bounded_status_only";
    } else if(kind==="repo_category"){
      if(!keys(packet,["kind","index_receipt"]))bad();const r=packet.index_receipt;
      if(!keys(r,["status","n8n_execution_id","observed_at","commit_sha","indexed_sources"])||
        r.status!=="SOURCES_INDEXED_NOT_DEPLOYED"||!number(r.n8n_execution_id)||!stamp(r.observed_at)||
        !commit(r.commit_sha)||!Number.isInteger(r.indexed_sources)||r.indexed_sources<1||r.indexed_sources>50)bad();
      status=r.status;reason="read_only_source_index";observedAt=r.observed_at;id="repo-category-readonly";
      receiptKey="repo-category-"+r.n8n_execution_id;
      version=receiptKey+":"+r.commit_sha+":"+status;url=base+"/blob/"+r.commit_sha+"/docs/REPOSITORY_UPLOAD_CATEGORY_DEPLOYMENT_HANDOFF_20261114.md";
      nextStep="Keep repository-category indexing manual and read-only; do not promote pinned sources to live tool status.";
      priority="normal";proof="manual_indexing_execution_metadata";
    } else {
      if(!keys(packet,["kind","market_receipt"]))bad();const r=packet.market_receipt;
      if(!keys(r,["status","reason","run_id","run_attempt","commit_sha","observed_at","orders_sent"])||
        !["BLOCKED","UNVERIFIED"].includes(r.status)||r.reason!=="SKIPPED_NO_ALPACA_DATA_CREDENTIALS"||
        !number(r.run_id)||!Number.isInteger(r.run_attempt)||r.run_attempt<1||!commit(r.commit_sha)||
        !stamp(r.observed_at)||r.orders_sent!==0)bad();
      status=r.status;reason=r.reason;observedAt=r.observed_at;id="market-desk-readonly";
      receiptKey="market-"+r.run_id+"-"+r.run_attempt;version=receiptKey+":"+status+":"+reason;
      url=base+"/actions/runs/"+r.run_id+"/attempts/"+r.run_attempt;
      nextStep="Securely provision read-only market data credentials and verify real GitHub ingestion; never place orders.";
      priority="high";proof="hosted_missing_data_credential_gate";
    }
    if(Date.parse(observedAt)>asOf+60000)bad();
    statuses.push({kind,status,reason,receipt_key:receiptKey,proof});
    rows.push({source:"github",id,version,title:kind.replaceAll("_"," ").toUpperCase()+" — "+status,
      next_step:nextStep,url,observed_at:observedAt,due_at:null,direction:"owner_action",priority});
  }
  const blocked=statuses.some(x=>["BLOCKED","FAILED"].includes(x.status));
  return {schema:"trivalley-chief-unified-handoff-v1",status:blocked?"BLOCKED":"PARTIAL_VERIFICATION",
    request_id:p.batch_id,records:statuses,chief_delivery:"normalized_output_prepared; acknowledgment_not_observed",
    chief_snapshot:{run_id:"mesh-"+p.batch_id,as_of:p.as_of,coverage:{github:"partial"},items:rows},
    limitations:["Manually supplied reviewed packets; this aggregator does not fetch artifacts or independently authenticate n8n executions.",
      "No new schedule, webhook, client contact, broker order, secret, image upload or Chief acknowledgment.",
      "Green CI, source pins and indexed repositories are not production acceptance."]};
}
const input = $('Reviewed evidence packets').first().json;
return [{json: normalizeBatch(input)}];
